"use client";

import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import {
  Activity, ArrowLeft, ArrowRight, ArrowUpRight, Bell, CalendarDays, Check, ChevronRight,
  Clock3, CreditCard, Dumbbell, Flame, Home, Info, LineChart, Loader2,
  MessageCircle, Minus, Play, Plus, RefreshCw, Search, Sparkles, Target, TrendingDown,
  TrendingUp, UserRoundPlus, UsersRound, WalletCards, X,
} from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Toaster } from "@/components/ui/sonner";
import { ExerciseDemonstration } from "@/components/exercise-demonstration";
import { BodyFatigueMap } from "@/components/body-fatigue-map";
import { RestTimer } from "@/components/rest-timer";
import { RoutineSheetEditor, RoutineTableView, makeRow, type RoutineDraftRow } from "@/components/routine-sheet";

type Role = "member" | "trainer" | "admin";
type View = "home" | "routine" | "progress" | "people";
type Exercise = { id: number; slug: string; name: string; muscle: string; equipment: string; instructions: string; mediaPath: string | null };
type Routine = { id: number; name: string; level: string; daysPerWeek: number; createdAt: string };
type RoutineExercise = Exercise & { routineId: number; exerciseId: number; dayName: string; dayTitle: string; position: number; sets: number; repsMin: number; repsMax: number; targetWeight: number; targetRir: number; restSeconds: number };
type Snapshot = {
  profile: { userId: string; email: string; displayName: string; role: string };
  membership: { id: number; plan: string; expiresAt: string; status: string };
  exercises: Exercise[]; routines: Routine[]; routineExercises: RoutineExercise[];
  assignments: { id: number; routineId: number; memberName: string; assignedAt: string; routineName: string }[];
  sessions: { id: number; routineName: string; startedAt: string; completedAt: string | null; durationSeconds: number }[];
  weights: { id: number; weight: number; recordedAt: string }[];
  muscleLoads: { muscle: string; completedAt: string; sets: number }[];
  lastPerformance: { exerciseId: number; weight: number; reps: number; rir: number | null; completedAt: string }[];
};

const members = [
  { name: "Martina López", plan: "Fuerza inicial", status: "Al día", initials: "ML" },
  { name: "Tomás Benítez", plan: "Hipertrofia 4D", status: "Revisar", initials: "TB" },
  { name: "Sofía Álvarez", plan: "Full body", status: "Al día", initials: "SA" },
  { name: "Nicolás Ruiz", plan: "Sin rutina", status: "Asignar", initials: "NR" },
];

async function requestGym(action?: Record<string, unknown>) {
  const response = await fetch("/api/gym", action ? { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(action) } : undefined);
  const data = await response.json() as Record<string, unknown>;
  if (!response.ok) throw new Error(typeof data.error === "string" ? data.error : "No pudimos completar la acción.");
  return data;
}

function LoginRequired({ onLoggedIn }: { onLoggedIn: () => void }) { return <main className="login-screen min-h-screen overflow-hidden text-white"><div className="login-brand"><Brand /><div className="login-copy"><p className="login-kicker">Tu próxima versión empieza acá</p><h1>Entrená con<br/><span>intención.</span></h1><p>Rutinas claras, progreso visible y tu entrenador siempre cerca.</p></div><div className="login-proof"><span><strong>01</strong> Planificá</span><span><strong>02</strong> Entrená</span><span><strong>03</strong> Evolucioná</span></div></div><AccountAccess onRefresh={onLoggedIn} required /></main>; }

export default function GymSpotterClient() {
  const [view, setView] = useState<View>("home");
  const [data, setData] = useState<Snapshot | null>(null);
  const [authUser, setAuthUser] = useState<{ userId: string; email: string; displayName: string; role?: string } | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedExercise, setSelectedExercise] = useState<Exercise | null>(null);
  const [workout, setWorkout] = useState<{ sessionId: number; exerciseIndex: number; dayName?: string } | null>(null);
  const [builderOpen, setBuilderOpen] = useState(false);
  const [assignOpen, setAssignOpen] = useState(false);
  const [weightOpen, setWeightOpen] = useState(false);
  const [editRoutineOpen, setEditRoutineOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);

  const load = useCallback(async () => {
    setLoading(true); setError("");
    if (!authUser) { setLoading(false); return; }
    try { setData(await requestGym() as unknown as Snapshot); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "No pudimos cargar tus datos."); }
    finally { setLoading(false); }
  }, [authUser]);

  const refreshAuth = useCallback(async () => {
    const response = await fetch("/api/auth");
    const payload = await response.json() as { user?: { userId: string; email: string; displayName: string; role?: string } | null };
    setAuthUser(payload.user ?? null);
    setAuthChecked(true);
  }, []);

  useEffect(() => { void refreshAuth(); }, [refreshAuth]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    const context = (document as Document & { modelContext?: { registerTool?: (tool: unknown, options?: { signal?: AbortSignal }) => void | Promise<void> } }).modelContext;
    if (!context?.registerTool) return;
    const lifecycle = new AbortController();
    void Promise.resolve(context.registerTool({ name: "open_routine_builder", title: "Crear rutina", description: "Abre el creador de rutinas del entrenador en GymSpotter.", inputSchema: { type: "object", properties: {}, additionalProperties: false }, annotations: { readOnlyHint: false, untrustedContentHint: false }, execute: async () => { setView("routine"); setBuilderOpen(true); return { status: "opened" }; } }, { signal: lifecycle.signal })).catch(() => undefined);
    return () => lifecycle.abort();
  }, []);

  const role = (data?.profile.role as Role | undefined) ?? (authUser?.role as Role | undefined) ?? "member";
  const roleLabel = role === "member" ? "Socio" : role === "trainer" ? "Entrenador" : "Administrador";
  const routine = data?.routines[0];
  const routineExercises = useMemo(() => data && routine ? data.routineExercises.filter((item) => item.routineId === routine.id) : [], [data, routine]);

  async function startWorkout(dayName?: string) {
    if (!routine) return;
    try {
      const result = await requestGym({ action: "start_workout", routineId: routine.id, routineName: routine.name });
      const session = result.session as { id: number };
      setWorkout({ sessionId: session.id, exerciseIndex: 0, dayName });
      toast.success("Entrenamiento guardado e iniciado");
    } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo iniciar."); }
  }

  if (!authChecked || (authUser && loading && !data)) return <main className="app-shell min-h-screen p-6 text-white"><LoadingState /></main>;
  if (!authUser) return <LoginRequired onLoggedIn={refreshAuth} />;
  const workoutExercises = workout?.dayName ? routineExercises.filter((exercise) => exercise.dayName === workout.dayName) : routineExercises;
  if (workout && workoutExercises.length) return <WorkoutMode routine={routine!} exercises={workoutExercises} lastPerformance={data?.lastPerformance ?? []} workout={workout} setWorkout={setWorkout} onRefresh={load} />;

  return <main className="app-shell min-h-screen pb-28 text-[#f3f4ee] lg:pb-8">
    <Toaster position="top-center" richColors />
    <Header roleLabel={roleLabel} name={data?.profile.displayName ?? authUser.displayName} email={authUser.email} onOpenAccount={() => setAccountOpen(true)} onLogout={async () => { await fetch("/api/auth", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "logout" }) }); setAccountOpen(false); setAuthUser(null); setData(null); }} />
    <div className="app-layout mx-auto grid max-w-[1440px] gap-7 px-4 py-5 sm:px-6 lg:grid-cols-[232px_minmax(0,1fr)] lg:py-8 xl:gap-10">
      <Sidebar role={role} view={view} onView={setView} />
      <section className="min-w-0">
        {loading && <LoadingState />}
        {!loading && error && <ErrorState message={error} onRetry={load} />}
        {!loading && data && role === "member" && <MemberArea data={data} view={view} routine={routine} exercises={routineExercises} onStart={startWorkout} onExercise={setSelectedExercise} onWeight={() => setWeightOpen(true)} onRefresh={load} onCreate={() => setBuilderOpen(true)} onEdit={() => setEditRoutineOpen(true)} />}
        {!loading && data && role === "trainer" && <TrainerArea data={data} view={view} onBuilder={() => setBuilderOpen(true)} onAssign={() => setAssignOpen(true)} />}
        {!loading && data && role === "admin" && <AdminArea data={data} view={view} onRefresh={load} />}
      </section>
    </div>
    <MobileNav role={role} view={view} onView={setView} />
    <AccountAccess role={data?.profile.role} onRefresh={async () => { await refreshAuth(); await load(); }} open={accountOpen} onOpenChange={setAccountOpen} showTrigger={false} />
    <ExerciseDialog exercise={selectedExercise} onClose={() => setSelectedExercise(null)} />
    {data && <RoutineBuilder open={builderOpen} onOpenChange={setBuilderOpen} exercises={data.exercises} onSaved={load} />}
    {data && routine && <RoutineEditorDialog open={editRoutineOpen} onOpenChange={setEditRoutineOpen} routine={routine} routineExercises={routineExercises} exercises={data.exercises} onSaved={load} />}
    {data && <AssignmentDialog open={assignOpen} onOpenChange={setAssignOpen} routines={data.routines} onSaved={load} />}
    {data && <WeightDialog open={weightOpen} onOpenChange={setWeightOpen} onSaved={load} />}
  </main>;
}

function MemberArea({ data, view, routine, exercises, onStart, onExercise, onWeight, onRefresh, onCreate, onEdit }: { data: Snapshot; view: View; routine?: Routine; exercises: RoutineExercise[]; onStart: (dayName?: string) => void; onExercise: (exercise: Exercise) => void; onWeight: () => void; onRefresh: () => void; onCreate: () => void; onEdit: () => void }) {
  if (view === "routine") return <RoutinePlan routine={routine} exercises={exercises} onExercise={onExercise} onStart={onStart} onCreate={onCreate} onEdit={onEdit} />;
  if (view === "progress") return <ProgressArea data={data} onWeight={onWeight} />;
  if (view === "people") return <TrainerContact />;
  const days = Math.max(0, Math.ceil((new Date(data.membership.expiresAt).getTime() - Date.now()) / 86400000));
  const latestWeight = data.weights[0]?.weight ?? 0;
  return <><PageTitle eyebrow={new Intl.DateTimeFormat("es-AR", { weekday: "long", day: "numeric", month: "long" }).format(new Date())} title="Hoy toca empujar." accessory={<span className="sync-status hidden items-center gap-2 text-sm text-white/55 sm:flex"><Flame className="size-4 text-orange-400" /> Listo para entrenar</span>} />
    <WeekStrip />
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.55fr)_minmax(290px,.8fr)]">
      <TodayWorkout routine={routine} exercises={exercises} onStart={onStart} onExercise={onExercise} />
      <div className="space-y-5"><Membership membership={data.membership} days={days} onRefresh={onRefresh} /><article className="rounded-[24px] border border-white/10 bg-[#121512] p-5"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-white/40">Peso corporal</p><p className="mt-3 text-4xl font-black">{latestWeight.toLocaleString("es-AR")} <span className="text-lg text-white/40">kg</span></p></div><Button onClick={onWeight} variant="outline" className="border-white/15 bg-white/5">+ Registrar</Button></div><p className="mt-3 flex items-center gap-1 text-sm text-[#c7ff3d]"><TrendingDown className="size-4" /> Evolución guardada en tu perfil</p></article></div>
    </div></>;
}

function WeekStrip() { const now = new Date(); return <article className="week-strip mb-5 rounded-[24px] border border-white/10 bg-[#121512] p-3 sm:p-4"><div className="grid grid-cols-7 gap-1 sm:gap-2">{Array.from({ length: 7 }, (_, index) => { const day = new Date(now); day.setDate(now.getDate() - now.getDay() + 1 + index); const active = day.toDateString() === now.toDateString(); return <div key={index} aria-current={active ? "date" : undefined} className={`min-w-0 rounded-xl px-1 py-2 text-center sm:rounded-2xl sm:px-3 ${active ? "bg-[#c7ff3d] text-black" : "text-white/45"}`}><span className="block text-xs font-bold uppercase">{new Intl.DateTimeFormat("es-AR", { weekday: "short" }).format(day).slice(0, 2)}</span><span className="mt-1 block text-xl font-black">{day.getDate()}</span><span className={`mx-auto mt-1 block size-1.5 rounded-full ${index === 0 || index === 2 || active ? "bg-current" : "bg-transparent"}`} /></div>; })}</div></article>; }

function TodayWorkout({ routine, exercises, onStart, onExercise }: { routine?: Routine; exercises: RoutineExercise[]; onStart: (dayName?: string) => void; onExercise: (exercise: Exercise) => void }) {
  const weekday = new Intl.DateTimeFormat("es-AR", { weekday: "long" }).format(new Date());
  const todayName = weekday.charAt(0).toUpperCase() + weekday.slice(1);
  const matchesToday = exercises.some((exercise) => exercise.dayName === todayName);
  const selectedDay = matchesToday ? todayName : exercises[0]?.dayName;
  const todayExercises = selectedDay ? exercises.filter((exercise) => exercise.dayName === selectedDay) : [];
  const dayTitle = todayExercises[0]?.dayTitle || "Entrenamiento del día";
  return <article className="workout-card overflow-hidden rounded-[28px] border border-white/10 bg-[#121512]"><div className="workout-card__head p-5 sm:p-7"><div><p className="text-sm font-bold text-white/55">{matchesToday ? "Entrenamiento de hoy" : "Próximo entrenamiento"} · {selectedDay ?? "Sin día asignado"}</p><h2 className="mt-2 text-3xl font-black">{dayTitle}</h2><p className="mt-3 flex flex-wrap items-center gap-2 text-sm text-white/50"><Clock3 className="size-4" /> {routine?.name ?? "Sin rutina"}<span>·</span><span>{todayExercises.length * 12} min</span><span>·</span><span>{todayExercises.length} ejercicios</span></p></div><div className="workout-index hidden sm:grid"><span>{String(todayExercises.length).padStart(2,"0")}</span><small>ejercicios</small></div></div><div className="exercise-list divide-y divide-white/8 border-y border-white/8 px-4 sm:px-6">{todayExercises.map((exercise, index) => <button key={exercise.id} onClick={() => onExercise(exercise)} className="group flex w-full items-center gap-4 rounded-xl px-2 py-4 text-left"><span className="exercise-number grid size-9 shrink-0 place-items-center rounded-full border border-white/15 text-sm font-black text-white/45">{index + 1}</span><span className="min-w-0 flex-1"><span className="block font-bold">{exercise.name}</span><span className="mt-1 block text-sm text-white/40">{exercise.sets} series · {exercise.repsMin}{exercise.repsMax !== exercise.repsMin ? `–${exercise.repsMax}` : ""} reps · {exercise.targetWeight || "—"} kg · RIR {exercise.targetRir}</span></span><ChevronRight className="size-4 text-white/25 transition-transform group-hover:translate-x-1" /></button>)}</div><div className="p-5 sm:p-6"><Button disabled={!routine || !todayExercises.length} onClick={() => onStart(selectedDay)} className="primary-action h-14 w-full rounded-2xl bg-[#e21b2d] text-base font-black text-white hover:bg-[#bd1626]"><Play className="fill-current" /> Empezar entrenamiento <ArrowRight className="ml-auto" /></Button></div></article>;
}

function Membership({ membership, days, onRefresh }: { membership: Snapshot["membership"]; days: number; onRefresh: () => void }) { const renew = async () => { try { await requestGym({ action: "renew_membership" }); await onRefresh(); toast.success("Membresía renovada por 30 días"); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo renovar."); } }; return <article className="rounded-[26px] bg-[#c7ff3d] p-5 text-black sm:p-6"><p className="text-xs font-black uppercase tracking-wider">Membresía activa</p><p className="mt-7 text-5xl font-black tracking-tight">{days}</p><p className="font-bold">días restantes</p><Progress value={Math.min(100, days / 30 * 100)} className="mt-5 bg-black/15 [&>div]:bg-black" /><div className="mt-3 flex justify-between text-xs font-bold text-black/55"><span>{membership.plan}</span><span>{new Date(membership.expiresAt).toLocaleDateString("es-AR", { day: "numeric", month: "short" })}</span></div><Button onClick={renew} className="mt-5 w-full bg-black font-bold text-white hover:bg-black/80">Renovar 30 días</Button></article>; }

function RoutinePlan({ routine, exercises, onExercise, onStart, onCreate, onEdit }: { routine?: Routine; exercises: RoutineExercise[]; onExercise: (exercise: Exercise) => void; onStart: () => void; onCreate: () => void; onEdit: () => void }) { return <><PageTitle eyebrow="Plan semanal" title={routine?.name ?? "Mi rutina"} accessory={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={onCreate} className="border-white/15 bg-white/5 font-bold">+ Crear rutina</Button>{routine && <Button variant="outline" onClick={onEdit} className="border-[#e21b2d]/50 bg-[#e21b2d]/10 font-bold text-white">Editar tabla</Button>}<Button onClick={onStart} disabled={!routine || !exercises.length} className="bg-[#e21b2d] font-black text-white"><Play /> Entrenar</Button></div>} /><RoutineTableView rows={exercises} onExercise={onExercise} /></>; }

function ProgressArea({ data, onWeight }: { data: Snapshot; onWeight: () => void }) { const completed = data.sessions.filter((item) => item.completedAt).length; const latest = data.weights[0]?.weight ?? 0; return <><PageTitle eyebrow="Datos reales de tu perfil" title="Tu progreso" accessory={<Button onClick={onWeight} className="bg-[#c7ff3d] font-black text-black"><Plus /> Registrar peso</Button>} /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Entrenamientos" value={String(completed)} detail="guardados" /><Metric label="Peso actual" value={`${latest.toLocaleString("es-AR")} kg`} detail="último registro" /><Metric label="Constancia" value={`${Math.max(1, completed)} sem.`} detail="racha activa" /></div><article className="mt-5 rounded-[26px] border border-white/10 bg-[#121512] p-5 sm:p-6"><div className="flex justify-between"><div><p className="text-sm text-white/45">Peso corporal</p><h2 className="text-2xl font-black">Evolución</h2></div><Target className="text-[#c7ff3d]" /></div><ProgressChart /></article><MuscleStatus loads={data.muscleLoads} /></>; }

function MuscleStatus({ loads }: { loads: Snapshot["muscleLoads"] }) { return <article className="mt-5 rounded-[26px] border border-white/10 bg-[#121512] p-5 sm:p-6"><div className="mb-5"><p className="text-sm text-white/45">Estado muscular</p><h2 className="text-2xl font-black">Fatiga estimada</h2></div><BodyFatigueMap loads={loads} /><p className="mt-4 text-center text-xs text-white/25">Estimación orientativa; no reemplaza una evaluación profesional.</p></article>; }

function TrainerArea({ data, view, onBuilder, onAssign }: { data: Snapshot; view: View; onBuilder: () => void; onAssign: () => void }) {
  if (view === "routine") return <RoutineLibrary data={data} onBuilder={onBuilder} onAssign={onAssign} />;
  if (view === "people") return <><PageTitle eyebrow="Cartera activa" title="Mis alumnos" accessory={<Button onClick={onAssign} className="bg-[#c7ff3d] font-black text-black"><Plus /> Asignar rutina</Button>} /><MemberList assignments={data.assignments} /></>;
  if (view === "progress") return <><PageTitle eyebrow="Seguimiento" title="Resultados del equipo" /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Rutinas creadas" value={String(data.routines.length)} detail="en tu biblioteca" /><Metric label="Asignaciones" value={String(data.assignments.length)} detail="persistidas" /><Metric label="Adherencia" value="82%" detail="promedio" /></div><article className="mt-5 rounded-[26px] border border-white/10 bg-[#121512] p-6"><ProgressChart /></article></>;
  return <><PageTitle eyebrow="Panel del entrenador" title="Diseñá. Asigná. Seguí." accessory={<Button onClick={onBuilder} className="bg-[#c7ff3d] font-black text-black"><Plus /> Crear rutina</Button>} /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Alumnos activos" value="24" detail="+3 este mes" /><Metric label="Rutinas propias" value={String(data.routines.length)} detail="guardadas" /><Metric label="Asignaciones" value={String(data.assignments.length)} detail="sincronizadas" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.8fr]"><article className="rounded-[26px] border border-white/10 bg-[#121512] p-5 sm:p-6"><h2 className="mb-3 text-xl font-black">Actividad de alumnos</h2><MemberList assignments={data.assignments} compact /></article><article className="rounded-[26px] bg-[#c7ff3d] p-6 text-black"><Sparkles className="size-8" /><h2 className="mt-6 text-2xl font-black">Creá planes desde cero.</h2><p className="mt-2 text-sm leading-6 text-black/65">Elegí ejercicios, frecuencia y nivel. Después asignalos a cualquier alumno.</p><Button onClick={onBuilder} className="mt-7 w-full bg-black font-bold text-white">Abrir creador</Button></article></div></>;
}

function RoutineLibrary({ data, onBuilder, onAssign }: { data: Snapshot; onBuilder: () => void; onAssign: () => void }) { return <><PageTitle eyebrow="Datos guardados en la nube" title="Biblioteca de rutinas" accessory={<Button onClick={onBuilder} className="bg-[#c7ff3d] font-black text-black"><Plus /> Nueva rutina</Button>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.routines.map((routine) => { const count = data.routineExercises.filter((item) => item.routineId === routine.id).length; return <article key={routine.id} className="rounded-[24px] border border-white/10 bg-[#121512] p-5"><div className="flex items-center justify-between"><div className="grid size-11 place-items-center rounded-xl bg-[#c7ff3d]/10 text-[#c7ff3d]"><Dumbbell /></div><span className="text-xs font-bold uppercase text-white/35">{routine.daysPerWeek} días</span></div><h2 className="mt-7 text-xl font-black">{routine.name}</h2><p className="mt-1 text-sm text-white/45">{count} ejercicios organizados por día</p><Button onClick={onAssign} className="mt-6 w-full bg-[#c7ff3d] font-bold text-black">Asignar a un alumno</Button></article>; })}</div></>; }

function MemberList({ assignments, compact = false }: { assignments: Snapshot["assignments"]; compact?: boolean }) { return <div className={compact ? "divide-y divide-white/8" : "grid gap-3"}>{members.map((member) => { const assigned = assignments.find((item) => item.memberName === member.name); return <div key={member.name} className={`flex items-center gap-4 ${compact ? "py-4" : "rounded-2xl border border-white/10 bg-[#121512] p-4"}`}><Avatar initials={member.initials} /><span className="min-w-0 flex-1"><span className="block font-bold">{member.name}</span><span className="text-sm text-white/40">{assigned?.routineName ?? member.plan}</span></span><span className={`text-xs font-bold ${assigned ? "text-[#c7ff3d]" : "text-amber-300"}`}>{assigned ? "Asignada" : member.status}</span></div>; })}</div>; }

function AdminArea({ data, view, onRefresh }: { data: Snapshot; view: View; onRefresh: () => void }) { const days = Math.max(0, Math.ceil((new Date(data.membership.expiresAt).getTime() - Date.now()) / 86400000)); if (view === "routine") return <><PageTitle eyebrow="Cobros y renovaciones" title="Membresías" /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Activas" value="428" detail="91% del total" /><Metric label="Por vencer" value="23" detail="próximos 7 días" /><Metric label="Tu plan de prueba" value={`${days} días`} detail="persistido" /></div></>; if (view === "people") return <><PageTitle eyebrow="Base de socios" title="Socios activos" accessory={<Button className="bg-[#c7ff3d] font-black text-black"><UserRoundPlus /> Nuevo socio</Button>} /><div className="mb-4 flex items-center gap-3 rounded-xl border border-white/10 bg-[#121512] px-4 py-3"><Search className="size-4 text-white/35" /><Input aria-label="Buscar socio" placeholder="Buscar por nombre" className="border-0 bg-transparent shadow-none" /></div><MemberList assignments={data.assignments} /></>; if (view === "progress") return <><PageTitle eyebrow="Rendimiento del negocio" title="Reportes" /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Renovación" value="87%" detail="+4,1%" /><Metric label="Ticket promedio" value="$42k" detail="este mes" /><Metric label="Altas netas" value="+18" detail="septiembre" /></div><article className="mt-5 rounded-[26px] border border-white/10 bg-[#121512] p-6"><ProgressChart /></article></>; return <><PageTitle eyebrow="Gestión del gimnasio" title="Todo bajo control." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Socios activos" value="428" detail="+18 este mes" /><Metric label="Ingresos" value="$14,8M" detail="+9,2%" /><Metric label="Por vencer" value="23" detail="contactar" /><Metric label="En el gimnasio" value="67" detail="ahora" /></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><article className="rounded-[26px] border border-white/10 bg-[#121512] p-6"><h2 className="text-xl font-black">Datos operativos</h2><p className="mt-2 text-sm leading-6 text-white/45">Membresías, rutinas y entrenamientos ya utilizan almacenamiento persistente.</p><Button onClick={onRefresh} variant="outline" className="mt-6 border-white/15 bg-white/5"><RefreshCw /> Sincronizar</Button></article><article className="rounded-[26px] border border-white/10 bg-[#121512] p-6"><h2 className="text-xl font-black">Ocupación de hoy</h2><MiniBars /></article></div></>; }

function WorkoutMode({ routine, exercises, lastPerformance, workout, setWorkout, onRefresh }: { routine: Routine; exercises: RoutineExercise[]; lastPerformance: Snapshot["lastPerformance"]; workout: { sessionId: number; exerciseIndex: number; dayName?: string }; setWorkout: (value: { sessionId: number; exerciseIndex: number; dayName?: string } | null) => void; onRefresh: () => void }) { const exercise = exercises[workout.exerciseIndex]; const last = lastPerformance.find((item) => item.exerciseId === exercise.exerciseId); const defaults = () => Array.from({ length: exercise.sets }, (_, index) => ({ number: index + 1, weight: last?.weight ?? exercise.targetWeight, reps: last?.reps ?? exercise.repsMin, rir: last?.rir ?? exercise.targetRir ?? 3, done: false })); const [sets, setSets] = useState(defaults); const [saving, setSaving] = useState(false); useEffect(() => { setSets(defaults()); }, [exercise.id]); const done = sets.filter((item) => item.done).length; const update = (index: number, key: "weight" | "reps" | "rir", delta: number) => setSets((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: Math.max(0, item[key] + delta) } : item)); const log = async (index: number) => { const item = sets[index]; setSaving(true); try { await requestGym({ action: "log_set", sessionId: workout.sessionId, exerciseId: exercise.exerciseId, setNumber: item.number, weight: item.weight, reps: item.reps, rir: item.rir }); setSets((current) => current.map((row, itemIndex) => itemIndex === index ? { ...row, done: true } : row)); toast.success(`Serie ${item.number} guardada`); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo guardar."); } finally { setSaving(false); } }; const finish = async () => { setSaving(true); try { await requestGym({ action: "complete_workout", sessionId: workout.sessionId }); await onRefresh(); setWorkout(null); toast.success("Entrenamiento finalizado"); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo finalizar."); } finally { setSaving(false); } }; return <main className="min-h-screen bg-black pb-8 text-white"><Toaster position="top-center" richColors /><header className="sticky top-0 z-20 border-b border-white/10 bg-black/90 px-4 py-4 backdrop-blur-xl"><div className="mx-auto flex max-w-3xl items-center justify-between"><Button onClick={() => setWorkout(null)} variant="ghost" size="icon" className="rounded-full bg-white/10"><X /></Button><div className="text-center"><p className="font-black">{routine.name}</p><p className="text-sm text-white/45">Ejercicio {workout.exerciseIndex + 1}/{exercises.length} · {done}/{sets.length} series</p></div><Button disabled={saving} onClick={finish} variant="ghost" size="icon" className="rounded-full bg-white/10 text-[#c7ff3d]"><Check /></Button></div><Progress value={(workout.exerciseIndex + done / sets.length) / exercises.length * 100} className="mx-auto mt-4 max-w-3xl bg-white/15" /></header><div className="mx-auto max-w-3xl px-4 py-6"><div className="overflow-hidden rounded-[26px] bg-[#171917]"><ExerciseDemonstration exercise={exercise} /></div><div className="mt-6 flex items-start justify-between gap-4"><div><h1 className="text-3xl font-black">{exercise.name}</h1><div className="mt-3 flex flex-wrap gap-2"><Pill>{exercise.muscle}</Pill><Pill>{exercise.equipment}</Pill><Pill>Descanso {exercise.restSeconds}s</Pill></div></div><Button onClick={() => toast.info(exercise.instructions)} variant="ghost" size="icon" className="rounded-full bg-white/10"><Info /></Button></div>{last && <p className="mt-4 text-sm text-white/50">Última vez: <strong className="text-white">{last.weight} kg × {last.reps} reps · RIR {last.rir ?? "—"}</strong></p>}<p className="mt-4 rounded-2xl border border-[#c7ff3d]/20 bg-[#c7ff3d]/8 p-4 text-sm leading-6 text-[#deff8c]">{exercise.instructions}</p><article className="mt-6 rounded-[26px] bg-[#171917] p-4 sm:p-6"><div className="mb-3 grid grid-cols-[34px_1fr_1fr_1fr_42px] gap-2 text-center text-xs font-bold uppercase text-white/35"><span /><span>Peso</span><span>Reps</span><span>RIR</span><span /></div><div className="space-y-3">{sets.map((item, index) => <div key={item.number} className="grid grid-cols-[34px_1fr_1fr_1fr_42px] items-center gap-2"><span className={`grid size-8 place-items-center rounded-full text-sm font-black ${item.done ? "bg-[#c7ff3d] text-black" : "bg-white/10 text-white/50"}`}>{item.done ? <Check className="size-4" /> : item.number}</span><Stepper value={item.weight} step={2.5} onChange={(delta) => update(index, "weight", delta)} /><Stepper value={item.reps} step={1} onChange={(delta) => update(index, "reps", delta)} /><Stepper value={item.rir} step={1} onChange={(delta) => update(index, "rir", delta)} /><button disabled={saving || item.done} onClick={() => log(index)} className={`grid size-10 place-items-center rounded-full border ${item.done ? "border-[#c7ff3d] bg-[#c7ff3d] text-black" : "border-white/20 text-white/45"}`} aria-label={`Guardar serie ${item.number}`}><Check className="size-5" /></button></div>)}</div></article><RestTimer embedded /><div className="mt-6 grid grid-cols-2 gap-3"><Button disabled={workout.exerciseIndex === 0} onClick={() => setWorkout({ ...workout, exerciseIndex: workout.exerciseIndex - 1 })} variant="outline" className="h-12 border-white/15 bg-white/5"><ArrowLeft /> Anterior</Button>{workout.exerciseIndex < exercises.length - 1 ? <Button onClick={() => setWorkout({ ...workout, exerciseIndex: workout.exerciseIndex + 1 })} className="h-12 bg-[#c7ff3d] font-black text-black">Siguiente <ArrowRight /></Button> : <Button onClick={finish} className="h-12 bg-[#c7ff3d] font-black text-black"><Check /> Finalizar</Button>}</div></div></main>; }

function Stepper({ value, step, onChange }: { value: number; step: number; onChange: (delta: number) => void }) { return <div className="flex h-12 items-center justify-between rounded-xl bg-white/5 px-1"><button onClick={() => onChange(-step)} className="grid size-8 place-items-center text-white/40" aria-label="Reducir"><Minus className="size-4" /></button><span className="text-sm font-bold">{value}</span><button onClick={() => onChange(step)} className="grid size-8 place-items-center text-white/70" aria-label="Aumentar"><Plus className="size-4" /></button></div>; }

function RoutineBuilder({ open, onOpenChange, exercises, onSaved }: { open: boolean; onOpenChange: (open: boolean) => void; exercises: Exercise[]; onSaved: () => void }) {
  const [name, setName] = useState("");
  const [rows, setRows] = useState<RoutineDraftRow[]>(() => [makeRow(exercises[0]?.id ?? 0)]);
  const [saving, setSaving] = useState(false);
  const save = async () => {
    setSaving(true);
    try {
      await requestGym({ action: "create_routine", name, daysPerWeek: new Set(rows.map((row) => row.dayName)).size, routineItems: rows.map(({ key: _key, ...row }) => row) });
      await onSaved(); setName(""); setRows([makeRow(exercises[0]?.id ?? 0)]); onOpenChange(false); toast.success("Rutina creada y guardada");
    } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo crear."); } finally { setSaving(false); }
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-[#171a17] text-white sm:max-w-5xl"><DialogHeader><DialogTitle className="text-2xl font-black">Crear rutina</DialogTitle><DialogDescription className="text-white/45">Poné un nombre general a la rutina y organizá cada día con su propio subtítulo.</DialogDescription></DialogHeader><label className="space-y-2 text-sm font-bold"><span>Nombre de la rutina</span><Input value={name} onChange={(event) => setName(event.target.value)} placeholder="Ej. Rutina semanal" className="border-white/15 bg-white/5" /></label><RoutineSheetEditor catalog={exercises} rows={rows} onChange={setRows} /><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)} className="border-white/15 bg-transparent">Cancelar</Button><Button disabled={saving || !name.trim() || !rows.length} onClick={save} className="bg-[#e21b2d] font-black text-white">{saving && <Loader2 className="animate-spin" />} Guardar rutina</Button></DialogFooter></DialogContent></Dialog>;
}

function RoutineEditorDialog({ open, onOpenChange, routine, routineExercises, exercises, onSaved }: { open: boolean; onOpenChange: (open: boolean) => void; routine: Routine; routineExercises: RoutineExercise[]; exercises: Exercise[]; onSaved: () => void }) {
  const [name, setName] = useState(routine.name);
  const [rows, setRows] = useState<RoutineDraftRow[]>([]);
  const [saving, setSaving] = useState(false);
  useEffect(() => { if (!open) return; setName(routine.name); setRows(routineExercises.map((item) => ({ key: `routine-${item.id}`, exerciseId: item.exerciseId, dayName: item.dayName, dayTitle: item.dayTitle ?? "", sets: item.sets, repsMin: item.repsMin, repsMax: item.repsMax, targetWeight: item.targetWeight, targetRir: item.targetRir ?? 3, restSeconds: item.restSeconds }))); }, [open, routine, routineExercises]);
  const save = async () => {
    setSaving(true);
    try {
      await requestGym({ action: "update_routine", routineId: routine.id, name, daysPerWeek: new Set(rows.map((row) => row.dayName)).size, routineItems: rows.map(({ key: _key, ...row }) => row) });
      await onSaved(); onOpenChange(false); toast.success("Rutina actualizada");
    } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo actualizar."); } finally { setSaving(false); }
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-[#171a17] text-white sm:max-w-5xl"><DialogHeader><DialogTitle className="text-2xl font-black">Editar rutina</DialogTitle><DialogDescription className="text-white/45">Elegí el día de la semana, agregá su subtítulo y modificá los objetivos desde la tabla.</DialogDescription></DialogHeader><label className="space-y-2 text-sm font-bold"><span>Nombre de la rutina</span><Input value={name} onChange={(event) => setName(event.target.value)} className="border-white/15 bg-white/5" /></label><RoutineSheetEditor catalog={exercises} rows={rows} onChange={setRows} /><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)} className="border-white/15 bg-transparent">Cancelar</Button><Button disabled={saving || !rows.length} onClick={save} className="bg-[#e21b2d] font-black text-white">{saving && <Loader2 className="animate-spin" />} Guardar cambios</Button></DialogFooter></DialogContent></Dialog>;
}

function AssignmentDialog({ open, onOpenChange, routines, onSaved }: { open: boolean; onOpenChange: (open: boolean) => void; routines: Routine[]; onSaved: () => void }) { const [member, setMember] = useState(members[0].name); const [routineId, setRoutineId] = useState(String(routines[0]?.id ?? "")); const [saving, setSaving] = useState(false); const save = async () => { setSaving(true); try { await requestGym({ action: "assign_routine", memberName: member, routineId: Number(routineId) }); await onSaved(); onOpenChange(false); toast.success(`Rutina asignada a ${member}`); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo asignar."); } finally { setSaving(false); } }; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="border-white/10 bg-[#171a17] text-white sm:max-w-md"><DialogHeader><DialogTitle className="text-2xl font-black">Asignar rutina</DialogTitle><DialogDescription className="text-white/45">El vínculo queda guardado en la base de datos.</DialogDescription></DialogHeader><label className="space-y-2 text-sm font-bold"><span>Alumno</span><Select value={member} onValueChange={setMember}><SelectTrigger className="w-full border-white/15 bg-white/5"><SelectValue /></SelectTrigger><SelectContent>{members.map((item) => <SelectItem key={item.name} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></label><label className="space-y-2 text-sm font-bold"><span>Rutina</span><Select value={routineId} onValueChange={setRoutineId}><SelectTrigger className="w-full border-white/15 bg-white/5"><SelectValue /></SelectTrigger><SelectContent>{routines.map((item) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></label><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)} className="border-white/15 bg-transparent">Cancelar</Button><Button disabled={saving || !routineId} onClick={save} className="bg-[#c7ff3d] font-black text-black">Asignar</Button></DialogFooter></DialogContent></Dialog>; }

function WeightDialog({ open, onOpenChange, onSaved }: { open: boolean; onOpenChange: (open: boolean) => void; onSaved: () => void }) { const [value, setValue] = useState("78.4"); const save = async () => { try { await requestGym({ action: "add_weight", value: Number(value) }); await onSaved(); onOpenChange(false); toast.success("Peso registrado"); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo guardar."); } }; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="border-white/10 bg-[#171a17] text-white sm:max-w-sm"><DialogHeader><DialogTitle className="text-2xl font-black">Registrar peso</DialogTitle><DialogDescription className="text-white/45">Se guardará con la fecha y hora actuales.</DialogDescription></DialogHeader><label className="space-y-2 text-sm font-bold"><span>Peso en kg</span><Input type="number" min="25" max="350" step="0.1" value={value} onChange={(event) => setValue(event.target.value)} className="border-white/15 bg-white/5 text-lg" /></label><DialogFooter><Button onClick={save} className="w-full bg-[#c7ff3d] font-black text-black">Guardar registro</Button></DialogFooter></DialogContent></Dialog>; }

function ExerciseDialog({ exercise, onClose }: { exercise: Exercise | null; onClose: () => void }) { return <Dialog open={!!exercise} onOpenChange={(open) => !open && onClose()}><DialogContent className="max-h-[90dvh] overflow-y-auto border-white/10 bg-[#171a17] p-0 text-white sm:max-w-xl">{exercise && <><ExerciseDemonstration exercise={exercise} /><div className="p-6"><DialogHeader><DialogTitle className="text-2xl font-black">{exercise.name}</DialogTitle><DialogDescription className="text-white/45">{exercise.muscle} · {exercise.equipment}</DialogDescription></DialogHeader><div className="mt-4 rounded-xl border border-[#c7ff3d]/20 bg-[#c7ff3d]/8 p-4"><p className="mb-1 text-xs font-bold uppercase tracking-wider text-[#c7ff3d]">Técnica</p><p className="text-sm leading-6 text-white/75">{exercise.instructions}</p></div><DialogFooter className="mt-5"><Button onClick={onClose} className="bg-[#c7ff3d] font-black text-black">Entendido</Button></DialogFooter></div></>}</DialogContent></Dialog>; }

function Header({ roleLabel, name, email, onOpenAccount, onLogout }: { roleLabel: string; name: string; email: string; onOpenAccount: () => void; onLogout: () => void }) { const [menuOpen, setMenuOpen] = useState(false); return <header className="app-header sticky top-0 z-30 border-b border-white/10 bg-[#090b0a]/90 backdrop-blur-xl"><div className="mx-auto flex min-h-20 max-w-[1440px] items-center justify-between gap-3 px-4 py-3 sm:px-6"><Brand /><div className="relative flex items-center gap-2"><Button aria-label="Notificaciones" variant="ghost" size="icon" className="hidden rounded-full text-white/70 sm:inline-flex"><Bell /></Button><button onClick={() => setMenuOpen((value) => !value)} aria-expanded={menuOpen} aria-label="Abrir menú de cuenta" className="profile-chip flex items-center gap-3 rounded-full border border-white/10 bg-white/5 py-1.5 pl-3 pr-1.5 text-left"><span className="hidden sm:block"><span className="block max-w-32 truncate text-sm font-bold text-white">{name}</span><span className="block text-xs text-white/40">{roleLabel}</span></span><span className="grid size-9 place-items-center rounded-full bg-[#e21b2d] text-xs font-black text-white">{name.split(" ").map((part) => part[0]).slice(0,2).join("")}</span></button>{menuOpen && <div className="account-menu absolute right-0 top-14 z-50 w-72 rounded-2xl border border-white/10 bg-[#17191d] p-4 shadow-2xl"><p className="text-xs font-black uppercase tracking-wider text-white/40">Sesión activa</p><p className="mt-2 font-bold">{name}</p><p className="truncate text-sm text-white/45">{email}</p><p className="mt-1 text-xs font-bold text-[#e21b2d]">{roleLabel}</p><div className="mt-4 grid gap-2"><Button onClick={() => { setMenuOpen(false); onOpenAccount(); }} variant="outline" className="border-white/15 bg-white/5">Gestionar cuenta</Button><Button onClick={() => { setMenuOpen(false); onLogout(); }} className="bg-[#e21b2d] font-black text-white">Cerrar sesión</Button></div></div>}</div></div></header>; }
function Brand() { return <div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-[#c7ff3d] text-black"><Dumbbell className="size-5" strokeWidth={2.6} /></div><div><p className="text-lg font-black tracking-[-.04em]">GYM<span className="text-[#c7ff3d]">SPOTTER</span></p><p className="hidden text-[11px] uppercase tracking-[.16em] text-white/40 sm:block">Athletic Club</p></div></div>; }
function Sidebar({ role, view, onView }: { role: Role; view: View; onView: (view: View) => void }) { const items = navItems(role); return <aside className="hidden lg:block"><nav aria-label="Navegación principal" className="side-nav sticky top-28 space-y-1 rounded-[24px] border border-white/8 bg-white/[.025] p-2">{items.map(([key, icon, label]) => <NavButton key={key} active={view === key} icon={icon} label={label} onClick={() => onView(key)} />)}<div className="side-nav__quote"><Target className="size-5"/><p>La constancia le gana a la motivación.</p></div></nav></aside>; }
function MobileNav({ role, view, onView }: { role: Role; view: View; onView: (view: View) => void }) { return <nav aria-label="Navegación principal" className="mobile-nav fixed inset-x-3 bottom-3 z-30 flex justify-around rounded-[22px] border border-white/10 bg-[#171a17]/95 p-2 shadow-2xl backdrop-blur-xl lg:hidden">{navItems(role).map(([key, icon, label]) => <button key={key} aria-current={view === key ? "page" : undefined} onClick={() => onView(key)} className={`flex min-w-16 flex-col items-center gap-1 rounded-2xl px-2 py-2 text-xs font-bold ${view === key ? "bg-[#c7ff3d] text-black" : "text-white/45"}`}><span className="[&>svg]:size-5">{icon}</span>{label}</button>)}</nav>; }
function navItems(role: Role): [View, ReactNode, string][] { if (role === "member") return [["home", <Home />, "Inicio"], ["routine", <Dumbbell />, "Rutina"], ["progress", <LineChart />, "Progreso"], ["people", <UsersRound />, "Entrenador"]]; if (role === "trainer") return [["home", <Home />, "Inicio"], ["people", <UsersRound />, "Alumnos"], ["routine", <Dumbbell />, "Rutinas"], ["progress", <LineChart />, "Resultados"]]; return [["home", <Home />, "Inicio"], ["people", <UsersRound />, "Socios"], ["routine", <CreditCard />, "Planes"], ["progress", <Activity />, "Reportes"]]; }
function NavButton({ active, icon, label, onClick }: { active: boolean; icon: ReactNode; label: string; onClick: () => void }) { return <button aria-current={active ? "page" : undefined} onClick={onClick} className={`flex w-full items-center gap-3 rounded-2xl px-4 py-3.5 text-sm font-bold [&>svg]:size-5 ${active ? "bg-[#c7ff3d] text-black" : "text-white/45 hover:bg-white/5 hover:text-white"}`}>{icon}{label}{active && <span className="ml-auto size-1.5 rounded-full bg-current" />}</button>; }
function PageTitle({ eyebrow, title, accessory }: { eyebrow: string; title: string; accessory?: ReactNode }) { return <div className="mb-6 flex flex-col items-start justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-1 text-sm font-bold uppercase tracking-[.13em] text-[#c7ff3d]">{eyebrow}</p><h1 className="text-3xl font-black tracking-[-.045em] sm:text-4xl">{title}</h1></div>{accessory}</div>; }
function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <article className="rounded-[22px] border border-white/10 bg-[#121512] p-5"><div className="flex justify-between"><p className="text-sm font-bold text-white/45">{label}</p><ArrowUpRight className="size-4 text-[#c7ff3d]" /></div><p className="mt-4 text-3xl font-black">{value}</p><p className="mt-1 text-xs font-bold text-[#c7ff3d]">{detail}</p></article>; }
function Stat({ label, value }: { label: string; value: string | number }) { return <div className="rounded-xl bg-white/5 p-3"><p className="text-xs text-white/35">{label}</p><p className="mt-1 text-sm font-bold">{value}</p></div>; }
function Pill({ children }: { children: ReactNode }) { return <span className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-xs font-bold text-white/55">{children}</span>; }
function Avatar({ initials }: { initials: string }) { return <span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-gradient-to-br from-[#dfff91] to-[#91c714] text-sm font-black text-black">{initials}</span>; }
function MiniBars() { return <div className="mt-6 flex h-32 items-end gap-2">{[28,45,72,96,64,82,48,88,70,52].map((height, index) => <span key={index} className={`flex-1 rounded-t-md ${index === 3 ? "bg-[#c7ff3d]" : "bg-white/10"}`} style={{ height: `${height}%` }} />)}</div>; }
function ProgressChart() { return <div className="mt-7 overflow-hidden"><svg viewBox="0 0 700 190" className="h-48 w-full" role="img" aria-label="Gráfico de progreso"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#c7ff3d" stopOpacity=".28"/><stop offset="1" stopColor="#c7ff3d" stopOpacity="0"/></linearGradient></defs>{[40,85,130,175].map((y) => <line key={y} x1="0" x2="700" y1={y} y2={y} stroke="white" strokeOpacity=".08" />)}<path d="M0 154 C70 145 82 132 140 137 S230 116 280 121 S360 92 420 98 S520 67 560 76 S640 35 700 42 L700 190 L0 190Z" fill="url(#area)"/><path d="M0 154 C70 145 82 132 140 137 S230 116 280 121 S360 92 420 98 S520 67 560 76 S640 35 700 42" fill="none" stroke="#c7ff3d" strokeWidth="5" strokeLinecap="round"/><circle cx="700" cy="42" r="7" fill="#c7ff3d" /></svg><div className="flex justify-between text-xs text-white/30"><span>Jun</span><span>Jul</span><span>Ago</span><span>Sep</span></div></div>; }
function TrainerContact() { return <><PageTitle eyebrow="Acompañamiento personal" title="Tu entrenador" /><article className="rounded-[26px] border border-white/10 bg-[#121512] p-6"><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><Avatar initials="MG" /><div className="flex-1"><h2 className="text-2xl font-black">Mateo González</h2><p className="text-white/45">Fuerza e hipertrofia</p></div><Button onClick={() => toast.success("Mensaje enviado")} className="bg-[#c7ff3d] font-black text-black"><MessageCircle /> Escribirle</Button></div><p className="mt-6 rounded-2xl bg-white/[.035] p-5 leading-7 text-white/70">“Muy buen control en el press. Mantené la carga y priorizá técnica limpia.”</p></article></>; }
function ExerciseCardSkeleton() { return <div className="h-40 animate-pulse rounded-2xl bg-white/5" />; }
function LoadingState() { return <div><div className="mb-6 h-10 w-64 animate-pulse rounded-xl bg-white/5" /><div className="grid gap-4 md:grid-cols-2"><ExerciseCardSkeleton /><ExerciseCardSkeleton /><ExerciseCardSkeleton /><ExerciseCardSkeleton /></div></div>; }
function ErrorState({ message, onRetry }: { message: string; onRetry: () => void }) { return <div className="grid min-h-[55vh] place-items-center"><div className="max-w-md rounded-[26px] border border-red-400/20 bg-red-400/5 p-7 text-center"><p className="text-xl font-black">No pudimos abrir tus datos</p><p className="mt-2 text-sm leading-6 text-white/45">{message}</p><Button onClick={onRetry} className="mt-5 bg-[#c7ff3d] font-black text-black"><RefreshCw /> Reintentar</Button></div></div>; }
function MemberRoutineActions({ hasRoutine, onCreate, onEdit }: { hasRoutine: boolean; onCreate: () => void; onEdit: () => void }) { return <div className="fixed bottom-20 left-4 z-30 flex gap-2 sm:bottom-6 sm:left-6"><button onClick={onCreate} className="rounded-full border border-white/10 bg-[#15171b] px-4 py-3 text-sm font-black text-white shadow-xl">+ Crear rutina</button>{hasRoutine && <button onClick={onEdit} className="rounded-full border border-[#e21b2d]/40 bg-[#e21b2d] px-4 py-3 text-sm font-black text-white shadow-xl">Editar</button>}</div>; }

function AccountAccess({ role, onRefresh, required = false, open: openProp, onOpenChange, showTrigger = true }: { role?: string; onRefresh: () => void; required?: boolean; open?: boolean; onOpenChange?: (open: boolean) => void; showTrigger?: boolean }) { const [openState, setOpenState] = useState(required); const open = openProp ?? openState; const setOpen = (value: boolean) => { setOpenState(value); onOpenChange?.(value); }; const [mode, setMode] = useState<"login" | "register">("login"); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [displayName, setDisplayName] = useState(""); const [newRole, setNewRole] = useState("member"); const [saving, setSaving] = useState(false); const canRegister = role === "admin"; const submit = async () => { setSaving(true); try { const response = await fetch("/api/auth", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(mode === "login" ? { action: "login", email, password } : { action: "register", email, password, displayName, role: newRole }) }); const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error || "No se pudo completar."); toast.success(mode === "login" ? "Sesión iniciada" : "Usuario registrado"); setOpen(false); setPassword(""); await onRefresh(); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "No se pudo completar."); } finally { setSaving(false); } }; return <>{showTrigger && !required && <button onClick={() => setOpen(true)} className="fixed right-4 top-20 z-30 rounded-full border border-white/10 bg-[#15171b]/95 px-3 py-2 text-xs font-black text-white/75 shadow-xl backdrop-blur-xl sm:right-6">{role ? "Mi cuenta" : "Ingresar"}</button>}<Dialog open={open} onOpenChange={(next) => { if (!required || next) setOpen(next); }}><DialogContent showCloseButton={!required} className="border-white/10 bg-[#171a17] text-white sm:max-w-md"><DialogHeader><DialogTitle className="text-2xl font-black">{role ? "Mi cuenta" : mode === "login" ? "Ingresar a GymSpotter" : "Registrar usuario"}</DialogTitle><DialogDescription className="text-white/45">{mode === "login" ? "Usá tu cuenta del gimnasio para cargar tus rutinas y progreso." : "El alta de usuarios queda reservada al administrador."}</DialogDescription></DialogHeader>{mode === "register" && <label className="space-y-2 text-sm font-bold"><span>Nombre</span><Input value={displayName} onChange={(event) => setDisplayName(event.target.value)} placeholder="Nombre completo" className="border-white/15 bg-white/5" /></label>}<label className="space-y-2 text-sm font-bold"><span>Email</span><Input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="vos@gimnasio.com" className="border-white/15 bg-white/5" /></label><label className="space-y-2 text-sm font-bold"><span>Contraseña</span><Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Mínimo 8 caracteres" className="border-white/15 bg-white/5" /></label>{mode === "register" && <label className="space-y-2 text-sm font-bold"><span>Rol</span><Select value={newRole} onValueChange={setNewRole}><SelectTrigger className="w-full border-white/15 bg-white/5"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="member">Socio</SelectItem><SelectItem value="trainer">Entrenador</SelectItem><SelectItem value="admin">Administrador</SelectItem></SelectContent></Select></label>}<DialogFooter className="flex-col gap-2 sm:flex-row">{canRegister && <Button variant="ghost" onClick={() => setMode(mode === "login" ? "register" : "login")} className="text-white/55">{mode === "login" ? "Registrar usuario" : "Volver a ingresar"}</Button>}<Button disabled={saving} onClick={submit} className="bg-[#e21b2d] font-black text-white">{saving && <Loader2 className="animate-spin" />}{mode === "login" ? "Ingresar" : "Crear usuario"}</Button></DialogFooter></DialogContent></Dialog></>; }
